#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        Entropy::new(v, EntropyUnit::JoulePerKelvin),
        Entropy::from_joules_per_kelvin(v)
    );
    assert_eq!(
        Entropy::from_base(v).convert_to(EntropyUnit::JoulePerKelvin),
        Entropy::from_base(v).as_joules_per_kelvin()
    );
    assert_eq!(
        Entropy::new(v, EntropyUnit::KilojoulePerKelvin),
        Entropy::from_kilojoules_per_kelvin(v)
    );
    assert_eq!(
        Entropy::from_base(v).convert_to(EntropyUnit::KilojoulePerKelvin),
        Entropy::from_base(v).as_kilojoules_per_kelvin()
    );
    assert_eq!(
        Entropy::new(v, EntropyUnit::MegajoulePerKelvin),
        Entropy::from_megajoules_per_kelvin(v)
    );
    assert_eq!(
        Entropy::from_base(v).convert_to(EntropyUnit::MegajoulePerKelvin),
        Entropy::from_base(v).as_megajoules_per_kelvin()
    );
    assert_eq!(
        Entropy::new(v, EntropyUnit::CaloriePerKelvin),
        Entropy::from_calories_per_kelvin(v)
    );
    assert_eq!(
        Entropy::from_base(v).convert_to(EntropyUnit::CaloriePerKelvin),
        Entropy::from_base(v).as_calories_per_kelvin()
    );
    assert_eq!(
        Entropy::new(v, EntropyUnit::KilocaloriePerKelvin),
        Entropy::from_kilocalories_per_kelvin(v)
    );
    assert_eq!(
        Entropy::from_base(v).convert_to(EntropyUnit::KilocaloriePerKelvin),
        Entropy::from_base(v).as_kilocalories_per_kelvin()
    );
    assert_eq!(
        Entropy::new(v, EntropyUnit::JoulePerDegreeCelsius),
        Entropy::from_joules_per_degree_celsius(v)
    );
    assert_eq!(
        Entropy::from_base(v).convert_to(EntropyUnit::JoulePerDegreeCelsius),
        Entropy::from_base(v).as_joules_per_degree_celsius()
    );
    assert_eq!(
        Entropy::new(v, EntropyUnit::KilojoulePerDegreeCelsius),
        Entropy::from_kilojoules_per_degree_celsius(v)
    );
    assert_eq!(
        Entropy::from_base(v).convert_to(EntropyUnit::KilojoulePerDegreeCelsius),
        Entropy::from_base(v).as_kilojoules_per_degree_celsius()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Entropy::from_base(v);
        let auto = q.auto_unit();
        assert_close(Entropy::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in EntropyUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        Entropy::from_base(0.0).auto_unit().unit,
        EntropyUnit::JoulePerKelvin
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "J/K".parse::<EntropyUnit>(),
        Ok(EntropyUnit::JoulePerKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "J/K").parse::<Entropy>(),
        Ok(Entropy::new(2.5, EntropyUnit::JoulePerKelvin))
    );
    assert_eq!(
        "kJ/K".parse::<EntropyUnit>(),
        Ok(EntropyUnit::KilojoulePerKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "kJ/K").parse::<Entropy>(),
        Ok(Entropy::new(2.5, EntropyUnit::KilojoulePerKelvin))
    );
    assert_eq!(
        "MJ/K".parse::<EntropyUnit>(),
        Ok(EntropyUnit::MegajoulePerKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "MJ/K").parse::<Entropy>(),
        Ok(Entropy::new(2.5, EntropyUnit::MegajoulePerKelvin))
    );
    assert_eq!(
        "cal/K".parse::<EntropyUnit>(),
        Ok(EntropyUnit::CaloriePerKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "cal/K").parse::<Entropy>(),
        Ok(Entropy::new(2.5, EntropyUnit::CaloriePerKelvin))
    );
    assert_eq!(
        "kcal/K".parse::<EntropyUnit>(),
        Ok(EntropyUnit::KilocaloriePerKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "kcal/K").parse::<Entropy>(),
        Ok(Entropy::new(2.5, EntropyUnit::KilocaloriePerKelvin))
    );
    assert_eq!(
        "J/°C".parse::<EntropyUnit>(),
        Ok(EntropyUnit::JoulePerDegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "J/°C").parse::<Entropy>(),
        Ok(Entropy::new(2.5, EntropyUnit::JoulePerDegreeCelsius))
    );
    assert_eq!(
        "kJ/°C".parse::<EntropyUnit>(),
        Ok(EntropyUnit::KilojoulePerDegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "kJ/°C").parse::<Entropy>(),
        Ok(Entropy::new(2.5, EntropyUnit::KilojoulePerDegreeCelsius))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Entropy>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = Entropy::from_base(6.0);
    let b = Entropy::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = Entropy::<i64>::from_base(7);
    let b = Entropy::<i64>::from_base(2);
    assert_eq!(a + b, Entropy::from_base(9));
    assert_eq!(a % b, Entropy::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!([a, b].iter().sum::<Entropy<i64>>(), Entropy::from_base(9));
}
